const TARGET_VOLUME = 0.4;

export default class Video {
  constructor(element) {
    this.dialog = element; // le <dialog data-component="Video">
    this.music = document.getElementById('music');
    this.soundBtn = document.getElementById('soundToggle');

    this.isOn = false;
    this.musicWasOn = false;
    this.userToggled = false;
    this.downTarget = null;

    this.initMusic();
    this.initVideoModal();
  }

  /* ---------- Musique ---------- */

  initMusic() {
    if (!this.music || !this.soundBtn) {
      console.warn('Video: #music ou #soundToggle est introuvable');
      return;
    }

    this.music.volume = TARGET_VOLUME;

    this.soundBtn.addEventListener('click', () => {
      this.userToggled = true;
      this.isOn ? this.pauseMusic() : this.playMusic();
    });

    document.addEventListener('visibilitychange', () => {
      if (!this.isOn) return;
      document.hidden ? this.music.pause() : this.music.play();
    });

    this.autoStart();
  }

  // Essaie de lancer la musique dès l'ouverture de la page.
  // Si le navigateur bloque, on attend la première interaction.
  autoStart() {
    this.music
      .play()
      .then(() => this.setState(true))
      .catch(() => {
        const events = ['click', 'keydown', 'touchend'];

        const cleanup = () =>
          events.forEach((ev) => document.removeEventListener(ev, start));

        const start = (e) => {
          // Si la personne a déjà utilisé le bouton son, on ne touche plus à rien
          if (this.userToggled) return cleanup();

          // Ces clics ont leur propre logique (bouton son, bouton vidéo)
          if (e.target.closest?.('#soundToggle, [data-video-open]')) return;

          cleanup();
          this.playMusic();
        };

        events.forEach((ev) => document.addEventListener(ev, start));
      });
  }

  setState(on) {
    this.isOn = on;
    this.soundBtn.setAttribute('aria-pressed', on);
    this.soundBtn.setAttribute(
      'aria-label',
      on ? 'Couper la musique' : 'Activer la musique',
    );
  }

  playMusic() {
    if (!this.music) return;
    this.music
      .play()
      .then(() => this.setState(true))
      .catch(() => {});
  }

  pauseMusic() {
    if (!this.music) return;
    this.music.pause();
    this.setState(false);
  }

  /* ---------- Modale vidéo ---------- */

  initVideoModal() {
    this.video = this.dialog.querySelector('video');
    this.closeBtn = this.dialog.querySelector('[data-video-close]');
    this.triggers = document.querySelectorAll('[data-video-open]');

    if (!this.video || !this.closeBtn) {
      console.warn(
        'Video: <video> ou [data-video-close] est introuvable dans la modale',
      );
      return;
    }

    this.triggers.forEach((t) =>
      t.addEventListener('click', (e) => {
        e.preventDefault();
        this.openVideo();
      }),
    );

    this.closeBtn.addEventListener('click', () => this.dialog.close());

    this.dialog.addEventListener(
      'pointerdown',
      (e) => (this.downTarget = e.target),
    );
    this.dialog.addEventListener('click', (e) => {
      if (e.target === this.dialog && this.downTarget === this.dialog)
        this.dialog.close();
    });

    this.dialog.addEventListener('close', () => this.onVideoClose());
    this.video.addEventListener('play', () => this.onVideoPlay());
  }

  openVideo() {
    this.dialog.showModal();
    this.video.play().catch(() => {});
  }

  onVideoPlay() {
    if (this.isOn) {
      this.musicWasOn = true;
      this.pauseMusic();
    }
  }

  onVideoClose() {
    this.video.pause();
    this.video.currentTime = 0;
    if (this.musicWasOn) {
      this.musicWasOn = false;
      this.playMusic();
    }
  }
}
